def _backfill() -> None:
    """Index the phone of invitations that are still open (decrypt -> HMAC, same keys as the app)."""
    from app.core.crypto import decrypt_field, hmac_sha256

    conn = op.get_bind()
    rows = conn.execute(
        sa.text(
            "SELECT id, invite_phone FROM contract_parties "
            "WHERE invite_token_hash IS NOT NULL AND user_id IS NULL AND invite_phone IS NOT NULL"
        )
    ).all()
    for pid, enc in rows:
        try:
            phone = decrypt_field(enc)
        except Exception:  # noqa: BLE001 - unreadable legacy row: leave it, the SMS token still works
            continue
        conn.execute(
            sa.text("UPDATE contract_parties SET invite_phone_hash = :h WHERE id = :id"),
            {"h": hmac_sha256(phone, purpose="invite_phone"), "id": pid},
        )


